@page "/courses"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4 align-items-end">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Search by title, code, or description..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td><a href="/courses/@course.Id">@course.Title</a></td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @courses.Count course(s)</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Enrollment.StudentName</strong> (ID: @Enrollment.StudentId).</p>
        <p>Your enrollment request for <strong>@(CatalogService.GetCourse(Enrollment.CourseId)?.Title ?? "the selected course")</strong> has been received.</p>
        <hr />
        <a href="/courses" class="btn btn-primary me-2">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary">Submit Another</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card shadow-sm">
                <div class="card-body">
                    <EditForm Model="Enrollment" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit" Enhance>
                        <DataAnnotationsValidator />
                        <AntiforgeryToken />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name</label>
                            <InputText id="studentName" class="form-control" @bind-Value="Enrollment.StudentName" />
                            <ValidationMessage For="() => Enrollment.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" class="form-control" @bind-Value="Enrollment.StudentId" />
                            <ValidationMessage For="() => Enrollment.StudentId" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="Enrollment.CourseId">
                                <option value="0">-- Select a Course --</option>
                                @foreach (var course in CatalogService.GetCourses(null, null))
                                {
                                    <option value="@course.Id">@course.Code — @course.Title</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => Enrollment.CourseId" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
                    </EditForm>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Enrollment { get; set; } = new();

    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (CatalogService.SubmitEnrollment(Enrollment))
        {
            Submitted = true;
        }
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4 align-items-end">
    <div class="col-md-5">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search" placeholder="Search by title, code, or description..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td><a href="/courses/@course.Id">@course.Title</a></td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Schedule</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @courses.Count course(s)</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Enrollment.StudentName</strong> (ID: @Enrollment.StudentId).</p>
        <p>Your enrollment request for <strong>@(CatalogService.GetCourse(Enrollment.CourseId)?.Title ?? "the selected course")</strong> has been received.</p>
        <hr />
        <a href="/courses" class="btn btn-primary me-2">Browse More Courses</a>
        <a href="/enroll" class="btn btn-outline-secondary">Submit Another</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card shadow-sm">
                <div class="card-body">
                    <EditForm Model="Enrollment" FormName="enrollment" method="post" OnValidSubmit="HandleSubmit" Enhance>
                        <DataAnnotationsValidator />
                        <AntiforgeryToken />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name</label>
                            <InputText id="studentName" class="form-control" @bind-Value="Enrollment.StudentName" />
                            <ValidationMessage For="() => Enrollment.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" class="form-control" @bind-Value="Enrollment.StudentId" />
                            <ValidationMessage For="() => Enrollment.StudentId" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="Enrollment.CourseId">
                                <option value="0">-- Select a Course --</option>
                                @foreach (var course in CatalogService.GetCourses(null, null))
                                {
                                    <option value="@course.Id">@course.Code — @course.Title</option>
                                }
                            </InputSelect>
                            <ValidationMessage For="() => Enrollment.CourseId" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment</button>
                    </EditForm>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Enrollment { get; set; } = new();

    private bool Submitted { get; set; }

    private void HandleSubmit()
    {
        if (CatalogService.SubmitEnrollment(Enrollment))
        {
            Submitted = true;
        }
    }
}

